"use client"

import type React from "react"
import { useEffect, useState } from "react"
import { useRouter, usePathname } from "next/navigation"
import { useAuthStore } from "@/lib/auth-store"

// Client-side guard. The real protection is server-side (proxy.ts + guard() on every API);
// this only avoids flashing protected UI. It waits for the persisted store to hydrate and
// confirms the httpOnly cookie session with /api/auth/me once per page load.
let verifiedThisLoad = false

export function AuthGuard({ children }: { children: React.ReactNode }) {
  const router = useRouter()
  const pathname = usePathname()
  const isAuthenticated = useAuthStore((s) => s.isAuthenticated)
  const verifySession = useAuthStore((s) => s.verifySession)
  const [hydrated, setHydrated] = useState(false)

  useEffect(() => {
    const p = (useAuthStore as any).persist
    if (!p || p.hasHydrated?.()) setHydrated(true)
    const unsub = p?.onFinishHydration?.(() => setHydrated(true))
    return () => { if (typeof unsub === "function") unsub() }
  }, [])

  useEffect(() => {
    if (!hydrated) return
    const toLogin = () => router.replace(`/login${pathname && pathname !== "/" ? `?next=${encodeURIComponent(pathname)}` : ""}`)
    if (!isAuthenticated) {
      // the cookie may still be valid (e.g. local storage cleared): ask the server before redirecting
      verifySession().then((ok) => { if (!ok) toLogin() })
    } else if (!verifiedThisLoad) {
      verifiedThisLoad = true
      verifySession().then((ok) => { if (!ok) toLogin() })
    }
  }, [hydrated, isAuthenticated, verifySession, router, pathname])

  if (!hydrated || !isAuthenticated) return null
  return <>{children}</>
}
